    text: "Pierwsze nowoczesne igrzyska olimpijskie w 1896 roku miały tylko 14 krajów i 241 zawodników. Nie było ceremonii otwarcia ani olimpijskiej flagi. Grecy wygrali tabele medali we własnym kraju.",
