    text: "Abraham Lincoln jest jedynym prezydentem USA posiadającym patent (nr 6469, 1849). Opatentował urządzenie unoszace statki na mielizne przez wypełnianie balonów powietrzem. Urządzenie nigdy nie zostało wyprodukowane.",
