    text: "W starożytnym Rzymie pralnie używały moczu ludzkiego jako detergentu — zawiera amoniak wybielający tkaniny. Przed lazieniami publicznymi stały pojemniki gdzie przechodnie mogli oddać mocz dla pralni.",
