    text: "Najdłużej panujący monarcha w historii to prawdopodobnie Pepi II z Egiptu — rzadzil ok. 90 lat (ok. 2278-2184 p.n.e.). Objął tron jako szesciolatka i jest najdłużej urzedujacym władca w dziejach.",
