    text: "Kobiety zostały dopuszczone do biegu maratońskiego na Igrzyskach Olimpijskich dopiero w 1984 r. w Los Angeles. Wcześniej uważano że to zbyt wyczerpujące dla kobiet. Kathrine Switzer w 1967 r. jako pierwsza kobieta ukończyła Boston Marathon — organizator próbował ja fizycznie usunąć z trasy.",
