    text: "Pierwsza kobieta która ukończyła Tour de France (jako wolontariuszka, 1983) jechała 42 dni. Kobiecy odpowiednik Tour — La Course — startuje od 2014 r. Kobiecy sport kolarski dopiero w ostatnich latach dostaje profesjonalne warunki.",
