    text: "Serena Williams wygrała Australian Open w 2017 r. będąc w 8 tygodniu ciąży. Wygrała 23 tytuły Slam singiel — więcej niż jakikolwiek zawodnik w erze Open. Zaczęła grać profesjonalnie w wieku 14 lat i grała na szczycie przez prawie 30 lat.",
