    text: "Curling wymaga precyzji do 1 cm przy rzucie kamienia wazacego 19 kg na odległość 29 m. Szorujacy zawodnicy mogą zmienić trajektorie i prędkość kamienia. To gra strategiczna z ogromna liczba możliwych ustawien w jednym endzie (rundzie).",
    category: "sports",
    emoji: "🥌",
