    text: "Taekwondo jest sportem olimpijskim od 2000 r. w Sydney. Pochodzi z Korei i kładzie nacisk na kopniecia. Oblicza się, że kopnięcie mistrza taekwondo niesie sile porownywalna z uderzeniem pojazdu jadącego 100 km/h.",
    category: "sports",
