    text: "Robert Lewandowski jest historycznie najlepszym strzelcem reprezentacji Polski. W sezonie 2020/21 strzelił 41 goli w jednym sezonie Bundesligi, pobijając ustanowiony niemal 50 lat wcześniej rekord Gerda Mullera.",
