    text: "Polska zupa pomidorowa (pomidorowa) jest jedna z ulubionych zup Polaków — badania pokazują że ok. 90% Polaków kocha ją szczególnie z makaronem lub ryżem. Pomidory dotarly do Polski stosunkowo późno — dopiero w XVIII w. Wcześniej uważano je za toksyczne.",
    category: "poland",
    emoji: "🍅",
