    text: "Pismo hieroglificzne zostało odszyfrowane przez Champolliona w 1822 r. dzięki kamieniowi z Rosetty (odkrytemu przez Napoleona w 1799 r.) — tablicy z tym samym tekstem po egipsku (hieroglify, demotyczny) i po grecku. Klucz był język grecki.",
