    text: "Język keczua — lingua franca Imperium Inków — nadal mówi ok. 8-10 mln ludzi w Peru, Boliwii i Ekwadorze. Jest oficjalnym językiem Peru obok hiszpańskiego. Wiele zapożyczeń z keczua weszlo do angielskiego: kondor, puma, lama, quinine (chinina).",
    category: "languages",
    emoji: "🦙",
