    text: "Język tajski ma 44 spolgloski, 32 samogloski i 5 tonów. Pismo tajskie nie ma spacji między slowami — czytelnik musi sam identyfikować granice słów. To jeden z powodów dlaczego tajski jest tak trudny dla obcokrajowców.",
