    id: "law2",
    text: "W Singapurze sprzedaż i przywozenie gumy do żucia jest nielegalne od 1992 roku. Można dostać grzywnę do 100 000 dolarów singapurskich. Wyjątkiem jest guma lecznicza przepisana przez dentystów. Prawo wprowadzono po serii incydentów z guma przyklejoną do drzwi metra.",
