    text: "W Arabii Saudyjskiej do niedawna prawo zakazywało kobietom prowadzenia samochodów. Zakaz ten obowiązywał przez dziesiątki lat i był jedynym takim na świecie. Dopiero w czerwcu 2018 roku kobiety oficjalnie dostały prawo do jazdy samochodem.",
