    text: "W Kanadzie 20% muzyki granej w radio musi być kanadyjskiego pochodzenia — to tzw. przepisy CanCon (Canadian Content). Prawo z 1971 roku zostało wprowadzone by chronić kanadyjskich artystów przed zalaniem stacji radiowych muzyka amerykańska. Dzisiaj Celine Dion i Nickelback to 'kontent obowiązkowy'.",
